content:
/* ==========================================================================
   Cafe Web Site Stylesheet
   Theme: Earth Warmth & Refined Minimalist (Mocha, Ivory, Sage Green)
   ========================================================================== */

:root {
  /* Color Palette */
  --color-primary: #6F4E37;        /* Coffee Mocha */
  --color-primary-dark: #4A3323;   /* Deep Espresso */
  --color-primary-light: #A47551;  /* Light Mocha */
  --color-accent: #5F7A61;         /* Sage Green */
  --color-accent-light: #8FA892;   /* Soft Sage */
  --color-accent-bg: #EAF0EB;      /* Light Sage Background */

  --color-bg: #FDFBF7;             /* Warm Ivory / Cream */
  --color-surface: #FFFFFF;        /* Pure White Card */
  --color-surface-alt: #F7F3EE;    /* Soft Muted Beige */
  --color-border: #E8E2D9;         /* Gentle Sand Border */
  --color-border-dark: #D4C9BC;

  --color-text-main: #2D2825;      /* Charcoal Charcoal Mocha */
  --color-text-sub: #6C625B;       /* Warm Slate Muted */
  --color-text-light: #9B9188;     /* Soft Ash Gray */
  --color-text-white: #FFFFFF;

  --color-gold: #C08A3E;           /* Muted Brass Accent */
  --color-badge-seasonal: #B4533C; /* Warm Rust Amber */
  --color-badge-rec: #5F7A61;      /* Sage Tag */

  /* Typography */
  --font-serif: "Shippori Mincho", "Noto Serif JP", "Yu Mincho", "Hiragino Mincho ProN", serif;
  --font-sans: "Zen Kaku Gothic New", "Noto Sans JP", "Hiragino Sans", -apple-system, BlinkMacSystemFont, sans-serif;
  --font-en: "Playfair Display", "Cinzel", "Times New Roman", serif;

  /* Shadows */
  --shadow-sm: 0 2px 8px rgba(74, 51, 35, 0.05);
  --shadow-md: 0 6px 20px rgba(74, 51, 35, 0.08);
  --shadow-lg: 0 12px 36px rgba(74, 51, 35, 0.12);
  --shadow-card: 0 4px 16px rgba(74, 51, 35, 0.06);

  /* Transitions */
  --transition-fast: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-normal: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-smooth: 0.5s cubic-bezier(0.16, 1, 0.3, 1);

  /* Spacings & Layout */
  --header-height: 72px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
}

/* Base Reset & Global Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.75;
  letter-spacing: 0.04em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  outline: none;
}

a {
  color: inherit;
  text-decoration: none;
}

/* App Wrapper */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--color-bg);
}

/* Navigation Bar */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(253, 251, 247, 0.94);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  border-bottom: 1px solid var(--color-border);
  transition: background-color var(--transition-normal), box-shadow var(--transition-normal);
}

.nav-brand {
  font-family: var(--font-en);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--color-primary-dark);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-links {
  display: flex;
  align-items: center;
  list-style: none;
  gap: 1.8rem;
}

.nav-item {
  font-size: 0.925rem;
  font-weight: 500;
  color: var(--color-text-sub);
  letter-spacing: 0.08em;
  transition: color var(--transition-fast);
  position: relative;
  padding: 0.4rem 0.2rem;
}

.nav-item::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 1.5px;
  background-color: var(--color-primary);
  transition: width var(--transition-fast);
}

.nav-item:hover {
  color: var(--color-primary);
}

.nav-item:hover::after {
  width: 100%;
}

.nav-reserve-btn {
  background-color: var(--color-primary);
  color: var(--color-text-white);
  padding: 0.6rem 1.4rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  transition: background-color var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  box-shadow: 0 2px 8px rgba(111, 78, 55, 0.25);
}

.nav-reserve-btn:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(111, 78, 55, 0.32);
}

/* Common Buttons */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: var(--color-primary);
  color: var(--color-text-white);
  padding: 0.85rem 2rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  box-shadow: 0 4px 14px rgba(111, 78, 55, 0.28);
  transition: all var(--transition-fast);
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  box-shadow: 0 6px 18px rgba(111, 78, 55, 0.35);
  transform: translateY(-2px);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: transparent;
  color: var(--color-primary-dark);
  border: 1.5px solid var(--color-primary-light);
  padding: 0.85rem 2rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  background-color: rgba(111, 78, 55, 0.08);
  border-color: var(--color-primary);
  color: var(--color-primary);
  transform: translateY(-2px);
}

/* Hero Section */
.hero-section {
  position: relative;
  min-height: 92vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: calc(var(--header-height) + 3rem) 2rem 5rem;
  background: radial-gradient(circle at 50% 20%, rgba(255, 255, 255, 0.85) 0%, rgba(247, 243, 238, 0.95) 75%),
              url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1920&q=80') center/cover no-repeat;
  overflow: hidden;
}

.hero-section::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(253, 251, 247, 0.4) 0%, rgba(253, 251, 247, 0.85) 100%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero-badge {
  display: inline-block;
  padding: 0.35rem 1.1rem;
  border-radius: var(--radius-full);
  background-color: var(--color-accent-bg);
  color: var(--color-accent);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  border: 1px solid rgba(95, 122, 97, 0.25);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 500;
  color: var(--color-primary-dark);
  line-height: 1.35;
  letter-spacing: 0.1em;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: clamp(1rem, 1.8vw, 1.15rem);
  color: var(--color-text-sub);
  line-height: 1.9;
  letter-spacing: 0.05em;
  margin-bottom: 2.5rem;
  max-width: 650px;
}

.hero-buttons {
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* Section Header (Common) */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3.5vw, 2.4rem);
  font-weight: 500;
  color: var(--color-primary-dark);
  letter-spacing: 0.12em;
  margin-bottom: 0.75rem;
  position: relative;
  display: inline-block;
}

.section-title::after {
  content: "";
  display: block;
  width: 40px;
  height: 2px;
  background-color: var(--color-gold);
  margin: 0.85rem auto 0;
  border-radius: 2px;
}

.section-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-sub);
  letter-spacing: 0.08em;
  line-height: 1.8;
}

/* Concept Section */
.concept-section {
  padding: 6.5rem 2rem;
  background-color: var(--color-surface);
}

.concept-container {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.concept-text {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  font-size: 1.025rem;
  color: var(--color-text-sub);
  line-height: 2;
}

.concept-text h3 {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 500;
  color: var(--color-primary-dark);
  letter-spacing: 0.08em;
  line-height: 1.5;
}

.concept-image-wrapper {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.concept-image-wrapper::before {
  content: "";
  position: absolute;
  top: -15px;
  left: -15px;
  right: 15px;
  bottom: 15px;
  border: 1px solid var(--color-border-dark);
  border-radius: var(--radius-md);
  z-index: -1;
}

.concept-image {
  width: 100%;
  height: 480px;
  object-fit: cover;
  display: block;
  transition: transform var(--transition-smooth);
}

.concept-image-wrapper:hover .concept-image {
  transform: scale(1.03);
}

/* Menu Section */
.menu-section {
  padding: 6.5rem 2rem;
  background-color: var(--color-surface-alt);
}

.category-tabs {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 3.5rem;
}

.tab-btn {
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-full);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  color: var(--color-text-sub);
  font-size: 0.925rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  border-color: var(--color-primary-light);
  color: var(--color-primary);
}

.tab-btn-active {
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(111, 78, 55, 0.25);
}

.tab-btn-active:hover {
  background-color: var(--color-primary);
  color: var(--color-text-white);
}

.menu-grid {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 2rem;
}

.menu-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(232, 226, 217, 0.7);
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
}

.menu-card-img-wrap {
  position: relative;
  width: 100%;
  height: 200px;
  overflow: hidden;
  background-color: var(--color-border);
}

.menu-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.menu-card:hover .menu-card-img {
  transform: scale(1.05);
}

.menu-card-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-text-white);
  background-color: var(--color-accent);
  letter-spacing: 0.05em;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}

.menu-card-body {
  padding: 1.4rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.menu-card-header {
  margin-bottom: 0.75rem;
}

.menu-item-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  letter-spacing: 0.04em;
  margin-bottom: 0.2rem;
}

.menu-item-en {
  font-family: var(--font-en);
  font-size: 0.8rem;
  color: var(--color-text-light);
  letter-spacing: 0.05em;
  margin-bottom: 0.4rem;
}

.menu-item-price {
  font-family: var(--font-en);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary);
  margin-top: 0.25rem;
}

.menu-item-desc {
  font-size: 0.875rem;
  color: var(--color-text-sub);
  line-height: 1.7;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px dashed var(--color-border);
}

/* Gallery Section */
.gallery-section {
  padding: 6.5rem 2rem;
  background-color: var(--color-surface);
}

.gallery-grid {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.gallery-item {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  height: 280px;
  box-shadow: var(--shadow-sm);
}

.gallery-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: rgba(74, 51, 35, 0.65);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--color-text-white);
  opacity: 0;
  transition: opacity var(--transition-normal);
  padding: 1.5rem;
  text-align: center;
  font-family: var(--font-serif);
  font-size: 1.1rem;
  letter-spacing: 0.08em;
}

.gallery-item:hover .gallery-img {
  transform: scale(1.06);
}

.gallery-item:hover .gallery-overlay {
  opacity: 1;
}

/* Access Section */
.access-section {
  padding: 6.5rem 2rem;
  background-color: var(--color-surface-alt);
}

.access-container {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 3.5rem;
  align-items: start;
}

.access-info-box {
  background-color: var(--color-surface);
  padding: 2.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.access-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 2rem;
}

.access-row {
  border-bottom: 1px solid var(--color-border);
}

.access-row:last-child {
  border-bottom: none;
}

.access-th {
  padding: 1rem 0;
  font-weight: 600;
  color: var(--color-primary-dark);
  font-size: 0.925rem;
  width: 32%;
  vertical-align: top;
  text-align: left;
}

.access-td {
  padding: 1rem 0;
  color: var(--color-text-sub);
  font-size: 0.925rem;
  line-height: 1.7;
}

.access-features {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--color-border);
}

.feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.85rem;
  background-color: var(--color-accent-bg);
  color: var(--color-accent);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 500;
}

.map-container {
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
  height: 100%;
  min-height: 380px;
  display: flex;
  flex-direction: column;
}

.map-visual {
  flex: 1;
  min-height: 320px;
  background-color: #E6EDF2;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-image: 
    radial-gradient(#D5E0E8 1.5px, transparent 1.5px),
    linear-gradient(to right, rgba(220, 228, 235, 0.4) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(220, 228, 235, 0.4) 1px, transparent 1px);
  background-size: 24px 24px, 48px 48px, 48px 48px;
}

.map-pin {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  filter: drop-shadow(0 4px 6px rgba(0,0,0,0.2));
  animation: floatPin 2.5s ease-in-out infinite alternate;
}

@keyframes floatPin {
  from {
    transform: translate(-50%, -100%);
  }
  to {
    transform: translate(-50%, -112%);
  }
}

/* Modal Window (Reservation) */
.reservation-modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(45, 40, 37, 0.65);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  z-index: 2000;
  animation: fadeIn var(--transition-fast) ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.reservation-modal {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 540px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
  padding: 2.5rem;
  position: relative;
  animation: scaleUp var(--transition-fast) ease-out;
}

@keyframes scaleUp {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(10px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-border);
}

.modal-title {
  font-family: var(--font-serif);
  font-size: 1.45rem;
  font-weight: 600;
  color: var(--color-primary-dark);
}

.modal-close {
  background: none;
  font-size: 1.5rem;
  color: var(--color-text-light);
  line-height: 1;
  padding: 0.3rem;
  border-radius: 50%;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-close:hover {
  color: var(--color-primary-dark);
  background-color: var(--color-surface-alt);
}

.reservation-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  text-align: left;
}

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-main);
  letter-spacing: 0.04em;
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-size: 0.95rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(111, 78, 55, 0.12);
  background-color: var(--color-surface);
}

.form-textarea {
  resize: vertical;
  min-height: 90px;
}

.modal-submit-btn {
  margin-top: 1rem;
  width: 100%;
  background-color: var(--color-primary);
  color: var(--color-text-white);
  padding: 0.9rem;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  box-shadow: 0 4px 12px rgba(111, 78, 55, 0.25);
  transition: all var(--transition-fast);
}

.modal-submit-btn:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(111, 78, 55, 0.32);
}

/* Toast Notification */
.toast-notification {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  background-color: var(--color-primary-dark);
  color: var(--color-text-white);
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
