import { useState } from 'react';
import { MENU_CATEGORIES, MENU_ITEMS } from '../data/cafeData';
import { MenuCategoryType, MenuItem } from '../types';

const MenuSection = () => {
  const [activeCategory, setActiveCategory] = useState<MenuCategoryType>('all');

  const filteredItems = activeCategory === 'all'
    ? MENU_ITEMS
    : MENU_ITEMS.filter((item) => item.category === activeCategory);

  const handleTabClick = (categoryId: MenuCategoryType) => {
    setActiveCategory(categoryId);
  };

  return (
    <section id="menu" className="menu-section">
      <div className="section-header">
        <h2 className="section-title">お品書き</h2>
        <p className="section-subtitle">
          直火焙煎の香り高い珈琲と、旬の恵みを閉じ込めた手作りのお菓子
        </p>
      </div>

      <div className="category-tabs">
        {MENU_CATEGORIES.map((category) => {
          const isActive = activeCategory === category.id;
          const buttonClass = isActive ? 'tab-btn tab-btn-active' : 'tab-btn';

          return (
            <button
              key={category.id}
              type="button"
              className={buttonClass}
              onClick={() => handleTabClick(category.id)}
            >
              {category.name}
            </button>
          );
        })}
      </div>

      <div className="menu-grid">
        {filteredItems.map((item: MenuItem) => (
          <article key={item.id} className="menu-card">
            <div className="menu-card-img-wrap">
              <img
                src={item.image}
                alt={item.name}
                className="menu-card-img"
                loading="lazy"
              />
              {item.isRecommended && (
                <span className="menu-card-badge" style={{ backgroundColor: 'var(--color-badge-rec)' }}>
                  おすすめ
                </span>
              )}
              {item.isSeasonal && !item.isRecommended && (
                <span className="menu-card-badge" style={{ backgroundColor: 'var(--color-badge-seasonal)' }}>
                  季節限定
                </span>
              )}
            </div>

            <div className="menu-card-body">
              <div className="menu-card-header">
                <h3 className="menu-item-name">{item.name}</h3>
                <p className="menu-item-en">{item.enName}</p>
                <div className="menu-item-price">¥{item.price.toLocaleString()}</div>
              </div>
              <p className="menu-item-desc">{item.description}</p>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
};

export default MenuSection;

import { useState, ChangeEvent, FormEvent } from 'react';
import { Coffee, Calendar, CheckCircle2, X } from 'lucide-react';
import { CAFE_INFO, CONCEPT_DATA, GALLERY_ITEMS } from './data/cafeData';
import { ReservationForm } from './types';
import MenuSection from './components/MenuSection';
import AccessSection from './components/AccessSection';

const INITIAL_RESERVATION: ReservationForm = {
  guestName: '',
  email: '',
  phone: '',
  date: '',
  time: '14:00',
  partySize: 2,
  notes: '',
};

const App = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [reservation, setReservation] = useState<ReservationForm>(INITIAL_RESERVATION);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const handleInputChange = (
    e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setReservation((prev) => ({
      ...prev,
      [name]: name === 'partySize' ? Number(value) : value,
    }));
  };

  const handleSubmitReservation = (e: FormEvent) => {
    e.preventDefault();
    if (!reservation.guestName || !reservation.date || !reservation.time || !reservation.phone) {
      return;
    }

    setIsModalOpen(false);
    setToastMessage(`${reservation.guestName}様、${reservation.date} ${reservation.time}のお席仮予約を受け付けました。`);
    setReservation(INITIAL_RESERVATION);

    setTimeout(() => {
      setToastMessage(null);
    }, 4500);
  };

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="cafe-app">
      {/* Navigation Bar */}
      <header className="navbar">
        <a href="#hero" className="nav-brand">
          <Coffee size={22} color="var(--color-primary)" />
          <span>{CAFE_INFO.enName}</span>
        </a>

        <ul className="nav-links">
          <li>
            <a href="#concept" className="nav-item">こだわり</a>
          </li>
          <li>
            <a href="#menu" className="nav-item">メニュー</a>
          </li>
          <li>
            <a href="#gallery" className="nav-item">ギャラリー</a>
          </li>
          <li>
            <a href="#access" className="nav-item">店舗・アクセス</a>
          </li>
        </ul>

        <button
          type="button"
          className="nav-reserve-btn"
          onClick={openModal}
        >
          席を予約する
        </button>
      </header>

      {/* Hero Section */}
      <section id="hero" className="hero-section">
        <div className="hero-content">
          <span className="hero-badge">Specialty Coffee & Sweets</span>
          <h1 className="hero-title">{CAFE_INFO.name}</h1>
          <p className="hero-subtitle">
            {CAFE_INFO.catchphrase}。
            日常の雑踏から離れ、心地よい珈琲の薫りと穏やかな音色に身を委ねるひとときを。
          </p>
          <div className="hero-buttons">
            <button
              type="button"
              className="btn-primary"
              onClick={() => scrollToSection('menu')}
            >
              メニューを見る
            </button>
            <button
              type="button"
              className="btn-outline"
              onClick={openModal}
            >
              Web席予約
            </button>
          </div>
        </div>
      </section>

      {/* Concept Section */}
      <section id="concept" className="concept-section">
        <div className="concept-container">
          <div className="concept-text">
            <div className="hero-badge" style={{ alignSelf: 'flex-start', margin: 0 }}>
              {CONCEPT_DATA.subtitle}
            </div>
            <h3>{CONCEPT_DATA.title}</h3>
            {CONCEPT_DATA.paragraphs.map((p, idx) => (
              <p key={idx}>{p}</p>
            ))}
          </div>

          <div className="concept-image-wrapper">
            <img
              src={CONCEPT_DATA.imageUrl}
              alt="こだわりのハンドドリップ珈琲"
              className="concept-image"
              loading="lazy"
            />
          </div>
        </div>
      </section>

      {/* Menu Section */}
      <MenuSection />

      {/* Gallery Section */}
      <section id="gallery" className="gallery-section">
        <div className="section-header">
          <h2 className="section-title">店内の風景</h2>
          <p className="section-subtitle">
            季節の移ろいとともに表情を変える、温もりあふれる空間
          </p>
        </div>

        <div className="gallery-grid">
          {GALLERY_ITEMS.map((item) => (
            <div key={item.id} className="gallery-item">
              <img
                src={item.image}
                alt={item.title}
                className="gallery-img"
                loading="lazy"
              />
              <div className="gallery-overlay">
                <span>{item.title}</span>
                <span style={{ fontSize: '0.8rem', marginTop: '0.4rem', opacity: 0.85 }}>
                  {item.enTitle}
                </span>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Access Section */}
      <AccessSection />

      {/* Footer */}
      <footer className="footer">
        <div className="footer-content">
          <div>
            <div className="footer-brand">{CAFE_INFO.enName}</div>
            <p style={{ marginTop: '0.4rem', fontSize: '0.9rem' }}>
              {CAFE_INFO.name} — {CAFE_INFO.address}
            </p>
            <p style={{ marginTop: '0.2rem', fontSize: '0.85rem' }}>
              TEL: {CAFE_INFO.phone} / {CAFE_INFO.hours}（定休日: {CAFE_INFO.holidays}）
            </p>
          </div>

          <div>
            <button
              type="button"
              className="btn-primary"
              onClick={openModal}
            >
              オンライン予約をする
            </button>
          </div>
        </div>

        <div className="footer-copy">
          &copy; {new Date().getFullYear()} {CAFE_INFO.name}. All rights reserved.
        </div>
      </footer>

      {/* Reservation Modal */}
      {isModalOpen && (
        <div
          className="reservation-modal-backdrop"
          onClick={closeModal}
          role="dialog"
          aria-modal="true"
        >
          <div
            className="reservation-modal"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h3 className="modal-title">お席のご予約</h3>
              <button
                type="button"
                className="modal-close"
                onClick={closeModal}
                aria-label="閉じる"
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmitReservation} className="reservation-form">
              <div className="form-group">
                <label className="form-label" htmlFor="guestName">お名前（必須）</label>
                <input
                  id="guestName"
                  name="guestName"
                  type="text"
                  required
                  placeholder="山田 太郎"
                  className="form-input"
                  value={reservation.guestName}
                  onChange={handleInputChange}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="phone">お電話番号（必須）</label>
                <input
                  id="phone"
                  name="phone"
                  type="tel"
                  required
                  placeholder="090-1234-5678"
                  className="form-input"
                  value={reservation.phone}
                  onChange={handleInputChange}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="email">メールアドレス</label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="example@boshiro.jp"
                  className="form-input"
                  value={reservation.email}
                  onChange={handleInputChange}
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div className="form-group">
                  <label className="form-label" htmlFor="date">ご来店日（必須）</label>
                  <input
                    id="date"
                    name="date"
                    type="date"
                    required
                    className="form-input"
                    value={reservation.date}
                    onChange={handleInputChange}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label" htmlFor="time">時間帯</label>
                  <select
                    id="time"
                    name="time"
                    className="form-select"
                    value={reservation.time}
                    onChange={handleInputChange}
                  >
                    <option value="10:30">10:30</option>
                    <option value="11:30">11:30</option>
                    <option value="13:00">13:00</option>
                    <option value="14:00">14:00</option>
                    <option value="15:30">15:30</option>
                    <option value="17:00">17:00</option>
                    <option value="18:30">18:30</option>
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="partySize">ご人数</label>
                <select
                  id="partySize"
                  name="partySize"
                  className="form-select"
                  value={reservation.partySize}
                  onChange={handleInputChange}
                >
                  <option value={1}>1名様（カウンター・テーブル）</option>
                  <option value={2}>2名様</option>
                  <option value={3}>3名様</option>
                  <option value={4}>4名様</option>
                  <option value={5}>5名様以上（お電話にて確認）</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="notes">ご要望・アレルギーなど</label>
                <textarea
                  id="notes"
                  name="notes"
                  className="form-textarea"
                  placeholder="電源席の希望、テラス席希望、車椅子でのご利用など"
                  value={reservation.notes}
                  onChange={handleInputChange}
                />
              </div>

              <button type="submit" className="modal-submit-btn">
                予約をリクエストする
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Toast Notification */}
      {toastMessage && (
        <div className="toast-notification">
          <CheckCircle2 size={20} color="var(--color-accent-light)" />
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  );
};

export default App;
